library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.wishbone_pkg.all;
use work.wbgenplus_pkg.all;
use work.genram_pkg.all;
use work.ebm_auto_pkg.all;

entity ebm_auto is
generic(
  g_adr_bits_hi : natural := 10 --Number of high address bits
);
Port(
  clk_sys_i     : std_logic;                                      -- Clock input for sys domain
  rst_sys_n_i   : std_logic;                                      -- Reset input (active low) for sys domain
  error_i       : in  std_logic_vector(1-1 downto 0);             -- Error control
  stall_i       : in  std_logic_vector(1-1 downto 0);             -- flow control
  status_i      : in  std_logic_vector(32-1 downto 0);            -- Status. 31..16: Packet counter. b2: Error b1: busy b0: configured
  status_V_i    : in  std_logic_vector(1-1 downto 0);             -- Valid flag - status
  adr_hi_o      : out std_logic_vector(g_adr_bits_hi-1 downto 0); -- High Address bits inserted into WB operations
  clear_o       : out std_logic_vector(1-1 downto 0);             -- Clears EBM buffers
  dst_ip_o      : out std_logic_vector(32-1 downto 0);            -- Destination IPV4 address
  dst_mac_o     : out std_logic_vector(48-1 downto 0);            -- Destination MAC address
  dst_port_o    : out std_logic_vector(16-1 downto 0);            -- Destination port number
  eb_opt_o      : out std_logic_vector(32-1 downto 0);            -- Default Record Header Options for current transaction
  flush_o       : out std_logic_vector(1-1 downto 0);             -- Send stored data as an EB packet
  mtu_o         : out std_logic_vector(16-1 downto 0);            -- Maximum packet size
  sema_o        : out std_logic_vector(32-1 downto 0);            -- Semaphore register in case multiple users want access
  src_ip_o      : out std_logic_vector(32-1 downto 0);            -- Source IPV4 address
  src_mac_o     : out std_logic_vector(48-1 downto 0);            -- Source MAC address
  src_port_o    : out std_logic_vector(16-1 downto 0);            -- Source port number
  udp_data_o    : out std_logic_vector(16-1 downto 0);            -- Raw udp Data input
  udp_data_WR_o : out std_logic_vector(1-1 downto 0);             -- Write enable flag - udp_data
  udp_raw_o     : out std_logic_vector(1-1 downto 0);             -- If this Flag is set, you can create raw udp packets by writing to udp_data
  
  slave_i       : in  t_wishbone_slave_in;
  slave_o       : out t_wishbone_slave_out

  
);
end ebm_auto;

architecture rtl of ebm_auto is

  signal s_pop, s_push    : std_logic;
  signal s_empty, s_full  : std_logic;
  signal r_e_wait, s_e_p  : std_logic;
  signal s_stall          : std_logic;
  signal s_valid,
         s_valid_ok,
         r_valid_check    : std_logic;
  signal r_ack            : std_logic;
  signal r_err            : std_logic;
  signal s_e, r_e, s_w    : std_logic;
  signal s_d              : std_logic_vector(32-1 downto 0);
  signal s_s              : std_logic_vector(4-1 downto 0);
  signal s_a              : std_logic_vector(5-1 downto 0);
  signal s_a_ext,
         r_a_ext0,
         r_a_ext1         : std_logic_vector(7-1 downto 0);
  signal r_error          : std_logic_vector(1-1 downto 0)              := std_logic_vector(to_unsigned(0, 1));     -- Error
  signal s_error_i        : std_logic_vector(1-1 downto 0)              := (others => '0');                         -- Error control
  signal s_stall_i        : std_logic_vector(1-1 downto 0)              := (others => '0');                         -- flow control
  signal r_clear          : std_logic_vector(1-1 downto 0)              := (others => '0');                         -- Clears EBM buffers
  signal r_flush          : std_logic_vector(1-1 downto 0)              := (others => '0');                         -- Send stored data as an EB packet
  signal r_status_V       : std_logic_vector(1-1 downto 0)              := (others => '0');                         -- Valid flag - status
  signal s_status_V_i     : std_logic_vector(1-1 downto 0)              := (others => '0');                         -- Valid flag - status
  signal r_status         : std_logic_vector(32-1 downto 0)             := (others => '0');                         -- Status. 31..16: Packet counter. b2: Error b1: busy b0: configured
  signal s_status_i       : std_logic_vector(32-1 downto 0)             := (others => '0');                         -- Status. 31..16: Packet counter. b2: Error b1: busy b0: configured
  signal r_src_mac        : std_logic_vector(48-1 downto 0)             := x"d15ea5edbabe";                         -- Source MAC address
  signal r_src_ip         : std_logic_vector(32-1 downto 0)             := x"deadbeef";                             -- Source IPV4 address
  signal r_src_port       : std_logic_vector(16-1 downto 0)             := x"ebd0";                                 -- Source port number
  signal r_dst_mac        : std_logic_vector(48-1 downto 0)             := x"ffffffffffff";                         -- Destination MAC address
  signal r_dst_ip         : std_logic_vector(32-1 downto 0)             := x"ffffffff";                             -- Destination IPV4 address
  signal r_dst_port       : std_logic_vector(16-1 downto 0)             := x"ebd0";                                 -- Destination port number
  signal r_mtu            : std_logic_vector(16-1 downto 0)             := std_logic_vector(to_unsigned(1500, 16)); -- Maximum packet size
  signal r_adr_hi         : std_logic_vector(g_adr_bits_hi-1 downto 0)  := (others => '0');                         -- High Address bits inserted into WB operations
  signal r_eb_opt         : std_logic_vector(32-1 downto 0)             := (others => '0');                         -- Default Record Header Options for current transaction
  signal r_sema           : std_logic_vector(32-1 downto 0)             := (others => '0');                         -- Semaphore register in case multiple users want access
  signal r_udp_raw        : std_logic_vector(1-1 downto 0)              := (others => '0');                         -- If this Flag  is set, you can create raw udp packets by writing to udp_data
  signal r_udp_data_WR    : std_logic_vector(1-1 downto 0)              := std_logic_vector(to_unsigned(0, 1));     -- Write enable flag - udp_data
  signal r_udp_data       : std_logic_vector(16-1 downto 0)             := (others => '0');                         -- Raw udp Data input


begin

  sp : wb_skidpad
  generic map(
    g_adrbits   => 5
  )
  Port map(
    clk_i        => clk_sys_i,
    rst_n_i      => rst_sys_n_i,
    push_i       => s_push,
    pop_i        => s_pop,
    full_o       => s_full,
    empty_o      => s_empty,
    adr_i        => slave_i.adr(6 downto 2),
    dat_i        => slave_i.dat,
    sel_i        => slave_i.sel,
    we_i         => slave_i.we,
    adr_o        => s_a,
    dat_o        => s_d,
    sel_o        => s_s,
    we_o         => s_w
  );

  validmux: with to_integer(unsigned(s_a_ext)) select
  s_valid <= 
  s_status_V_i(0) when c_status_GET,  -- 
  '1'             when others;
  
  s_valid_ok        <=  r_valid_check and s_valid;
  s_e_p             <=  r_e or r_e_wait;
  s_a_ext           <= s_a & "00";
  s_stall           <= s_full;
  s_push            <= slave_i.cyc and slave_i.stb and not s_stall;
  s_e               <= not (s_empty or s_e_p);
  s_pop             <= s_valid_ok;
  slave_o.stall     <= s_stall;
  
  s_error_i     <= error_i;
  s_stall_i     <= stall_i;
  clear_o       <= r_clear;
  flush_o       <= r_flush;
  s_status_V_i  <= status_V_i;
  s_status_i    <= status_i;
  src_mac_o     <= r_src_mac;
  src_ip_o      <= r_src_ip;
  src_port_o    <= r_src_port;
  dst_mac_o     <= r_dst_mac;
  dst_ip_o      <= r_dst_ip;
  dst_port_o    <= r_dst_port;
  mtu_o         <= r_mtu;
  adr_hi_o      <= r_adr_hi;
  eb_opt_o      <= r_eb_opt;
  sema_o        <= r_sema;
  udp_raw_o     <= r_udp_raw;
  udp_data_WR_o <= r_udp_data_WR;
  udp_data_o    <= r_udp_data;
  
  slave : process(clk_sys_i)
  begin
    if rising_edge(clk_sys_i) then
      if(rst_sys_n_i = '0') then
        r_e           <= '0';
        r_e_wait      <= '0';
        r_valid_check <= '0';
        r_error       <= std_logic_vector(to_unsigned(0, 1));
        r_clear       <= (others => '0');
        r_flush       <= (others => '0');
        r_status      <= (others => '0');
        r_src_mac     <= x"d15ea5edbabe";
        r_src_ip      <= x"deadbeef";
        r_src_port    <= x"ebd0";
        r_dst_mac     <= x"ffffffffffff";
        r_dst_ip      <= x"ffffffff";
        r_dst_port    <= x"ebd0";
        r_mtu         <= std_logic_vector(to_unsigned(1500, 16));
        r_adr_hi      <= (others => '0');
        r_eb_opt      <= (others => '0');
        r_sema        <= (others => '0');
        r_udp_raw     <= (others => '0');
        r_udp_data_WR <= std_logic_vector(to_unsigned(0, 1));
        r_udp_data    <= (others => '0');
      else
        r_e           <= s_e;
        r_a_ext0      <= s_a_ext;
        r_a_ext1      <= r_a_ext0;
        r_e_wait      <= s_e_p and not s_valid_ok;
        r_valid_check <= (r_valid_check or (s_e_p and not stall_i(0))) and not s_valid_ok;
        r_ack         <= s_pop and not (error_i(0) or r_error(0));
        r_err         <= s_pop and     (error_i(0) or r_error(0));
        slave_o.ack   <= r_ack;
        slave_o.err   <= r_err;
        
        
        if stall_i = "0" then
          r_clear       <= (others => '0');
          r_error       <= (others => '0');
          r_flush       <= (others => '0');
          r_udp_data_WR <= (others => '0');
        end if;
        
        if s_status_V_i = "1" then r_status <= s_status_i; end if;  -- 
        
        
        if(s_e = '1') then
          if(s_w = '1') then
            -- WISHBONE WRITE ACTIONS
            case to_integer(unsigned(s_a_ext)) is
              when c_clear_OWR          => r_clear                  <= f_wb_wr(r_clear, s_d, s_s, "owr");                 -- 
              when c_flush_OWR          => r_flush                  <= f_wb_wr(r_flush, s_d, s_s, "owr");                 -- 
              when c_src_mac_RW_0       => r_src_mac(31 downto 0)   <= f_wb_wr(r_src_mac(31 downto 0), s_d, s_s, "owr");  -- 
              when c_src_mac_RW_1       => r_src_mac(47 downto 32)  <= f_wb_wr(r_src_mac(47 downto 32), s_d, s_s, "owr"); -- 
              when c_src_ip_RW          => r_src_ip                 <= f_wb_wr(r_src_ip, s_d, s_s, "owr");                -- 
              when c_src_port_RW        => r_src_port               <= f_wb_wr(r_src_port, s_d, s_s, "owr");              -- 
              when c_dst_mac_RW_0       => r_dst_mac(31 downto 0)   <= f_wb_wr(r_dst_mac(31 downto 0), s_d, s_s, "owr");  -- 
              when c_dst_mac_RW_1       => r_dst_mac(47 downto 32)  <= f_wb_wr(r_dst_mac(47 downto 32), s_d, s_s, "owr"); -- 
              when c_dst_ip_RW          => r_dst_ip                 <= f_wb_wr(r_dst_ip, s_d, s_s, "owr");                -- 
              when c_dst_port_RW        => r_dst_port               <= f_wb_wr(r_dst_port, s_d, s_s, "owr");              -- 
              when c_mtu_RW             => r_mtu                    <= f_wb_wr(r_mtu, s_d, s_s, "owr");                   -- 
              when c_adr_hi_RW          => r_adr_hi                 <= f_wb_wr(r_adr_hi, s_d, s_s, "owr");                -- 
              when c_eb_opt_RW          => r_eb_opt                 <= f_wb_wr(r_eb_opt, s_d, s_s, "owr");                -- 
              when c_sema_RW            => r_sema                   <= f_wb_wr(r_sema, s_d, s_s, "owr");                  -- 
              when c_udp_raw_RW         => r_udp_raw                <= f_wb_wr(r_udp_raw, s_d, s_s, "owr");               -- 
              when c_udp_data_OWR       => r_udp_data               <= f_wb_wr(r_udp_data, s_d, s_s, "owr");              -- 
              r_udp_data_WR                                         <= (others  => '1');
              when others               => r_error                  <= "1";
            end case;
          else
            -- WISHBONE READ ACTIONS
            case to_integer(unsigned(s_a_ext)) is
              when c_status_GET   => null;
              when c_src_mac_RW_0 => null;
              when c_src_mac_RW_1 => null;
              when c_src_ip_RW    => null;
              when c_src_port_RW  => null;
              when c_dst_mac_RW_0 => null;
              when c_dst_mac_RW_1 => null;
              when c_dst_ip_RW    => null;
              when c_dst_port_RW  => null;
              when c_mtu_RW       => null;
              when c_adr_hi_RW    => null;
              when c_eb_opt_RW    => null;
              when c_sema_RW      => null;
              when c_udp_raw_RW   => null;
              when others         => r_error <= "1";
            end case;
          end if; -- s_w
        end if; -- s_e
        
        case to_integer(unsigned(r_a_ext1)) is
          when c_status_GET   => slave_o.dat  <= std_logic_vector(resize(unsigned(r_status), slave_o.dat'length));                  -- 
          when c_src_mac_RW_0 => slave_o.dat  <= std_logic_vector(resize(unsigned(r_src_mac(31 downto 0)), slave_o.dat'length));    -- 
          when c_src_mac_RW_1 => slave_o.dat  <= std_logic_vector(resize(unsigned(r_src_mac(47 downto 32)), slave_o.dat'length));   -- 
          when c_src_ip_RW    => slave_o.dat  <= std_logic_vector(resize(unsigned(r_src_ip), slave_o.dat'length));                  -- 
          when c_src_port_RW  => slave_o.dat  <= std_logic_vector(resize(unsigned(r_src_port), slave_o.dat'length));                -- 
          when c_dst_mac_RW_0 => slave_o.dat  <= std_logic_vector(resize(unsigned(r_dst_mac(31 downto 0)), slave_o.dat'length));    -- 
          when c_dst_mac_RW_1 => slave_o.dat  <= std_logic_vector(resize(unsigned(r_dst_mac(47 downto 32)), slave_o.dat'length));   -- 
          when c_dst_ip_RW    => slave_o.dat  <= std_logic_vector(resize(unsigned(r_dst_ip), slave_o.dat'length));                  -- 
          when c_dst_port_RW  => slave_o.dat  <= std_logic_vector(resize(unsigned(r_dst_port), slave_o.dat'length));                -- 
          when c_mtu_RW       => slave_o.dat  <= std_logic_vector(resize(unsigned(r_mtu), slave_o.dat'length));                     -- 
          when c_adr_hi_RW    => slave_o.dat  <= std_logic_vector(resize(unsigned(r_adr_hi), slave_o.dat'length));                  -- 
          when c_eb_opt_RW    => slave_o.dat  <= std_logic_vector(resize(unsigned(r_eb_opt), slave_o.dat'length));                  -- 
          when c_sema_RW      => slave_o.dat  <= std_logic_vector(resize(unsigned(r_sema), slave_o.dat'length));                    -- 
          when c_udp_raw_RW   => slave_o.dat  <= std_logic_vector(resize(unsigned(r_udp_raw), slave_o.dat'length));                 -- 
          when others         => slave_o.dat  <= (others => 'X');
        end case;

        
      end if; -- rst
    end if; -- clk edge
  end process;

end rtl;
